import numbers


def analyze_column_against_mean(data, column, value):
    if column not in data:
        raise ValueError(f"Column '{column}' not found in data.")
    if not isinstance(value, numbers.Real) or isinstance(value, bool):
        raise ValueError("Value must be a number.")

    col_values = data[column]
    if not col_values:
        return ([], 0)

    mean = sum(col_values) / len(col_values)
    above_mean = [x for x in col_values if x > mean]
    count = sum(1 for x in col_values if x > value)

    return (above_mean, count)
