def top_selling_product(csv_text: str) -> str:
    reader = csv.DictReader(io.StringIO(csv_text))
    if (
        not reader.fieldnames
        or "product" not in reader.fieldnames
        or "quantity" not in reader.fieldnames
    ):
        raise ValueError("CSV must contain 'product' and 'quantity' columns.")

    totals: dict[str, int] = {}
    for row in reader:
        product = row["product"]
        qty_str = row["quantity"]
        if qty_str is None:
            raise ValueError(f"Missing quantity for product {product!r}.")
        try:
            quantity = int(qty_str)
        except ValueError as exc:
            raise ValueError(
                f"Invalid integer quantity {qty_str!r} for product {product!r}."
            ) from exc
        totals[product] = totals.get(product, 0) + quantity

    if not totals:
        raise ValueError("CSV contains no data rows.")

    return max(totals, key=totals.get)
