import base64
import binascii
import hashlib
import hmac


def verify_hmac_sha1(message_b64: str, signature: str, secret_key: str) -> bool:
    if not isinstance(message_b64, (str, bytes)):
        raise ValueError("message_b64 must be a valid base64 string")

    try:
        message_bytes = base64.b64decode(message_b64, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("Invalid base64-encoded message") from exc

    if not isinstance(signature, str):
        return False

    key_bytes = secret_key.encode("utf-8")
    expected_signature = hmac.new(key_bytes, message_bytes, hashlib.sha1).hexdigest()

    try:
        return hmac.compare_digest(expected_signature, signature)
    except TypeError:
        return False
```

