from collections import defaultdict


def count_subset_sums(elements, subset_size):
    n = len(elements)
    if subset_size < 0 or subset_size > n:
        return {}
    if subset_size == 0:
        return {0: 1}

    dp = [defaultdict(int) for _ in range(subset_size + 1)]
    dp[0][0] = 1

    for i, value in enumerate(elements):
        min_k = max(1, subset_size - (n - 1 - i))
        max_k = min(i + 1, subset_size)
        for k in range(max_k, min_k - 1, -1):
            for current_sum, count in dp[k - 1].items():
                dp[k][current_sum + value] += count

    return dict(dp[subset_size])
