import ast
from typing import List, Optional


def _find_matching_brace(text: str, start: int) -> Optional[int]:
    """Return the exclusive end index of the brace block starting at `start`, or None."""
    n = len(text)
    stack = ["{"]
    i = start + 1

    while i < n:
        ch = text[i]

        # Skip Python comments until the end of the line
        if ch == "#":
            nl = text.find("\n", i + 1)
            if nl == -1:
                return None
            i = nl + 1
            continue

        # Skip string literals (single, double, and triple-quoted)
        if ch in ("'", '"'):
            triple = ch * 3
            if text.startswith(triple, i):
                i += 3
                while i < n:
                    c = text[i]
                    if c == "\\":
                        i += 2
                    elif text.startswith(triple, i):
                        i += 3
                        break
                    else:
                        i += 1
                else:
                    return None
                continue
            else:
                i += 1
                closed = False
                while i < n:
                    c = text[i]
                    if c == "\\":
                        if i + 2 < n and text[i + 1] == "\r" and text[i + 2] == "\n":
                            i += 3
                        else:
                            i += 2
                    elif c in ("\n", "\r"):
                        return None
                    elif c == ch:
                        i += 1
                        closed = True
                        break
                    else:
                        i += 1
                if not closed:
                    return None
                continue

        # Track nested braces, brackets, and parentheses
        if ch in "{[(":
            stack.append(ch)
        elif ch in "}])":
            if not stack:
                return None
            top = stack[-1]
            if (
                (top == "{" and ch == "}")
                or (top == "[" and ch == "]")
                or (top == "(" and ch == ")")
            ):
                stack.pop()
                if not stack:
                    return i + 1
            else:
                return None

        i += 1

    return None


def extract_dicts(text: str) -> List[dict]:
    """Find every outermost Python dictionary literal in `text` and return them as dicts."""
    dicts: List[dict] = []
    n = len(text)
    i = 0

    while i < n:
        pos = text.find("{", i)
        if pos == -1:
            break

        end = _find_matching_brace(text, pos)
        if end is not None:
            candidate = text[pos:end]
            try:
                value = ast.literal_eval(candidate)
            except (ValueError, SyntaxError, TypeError, RecursionError):
                i = pos + 1
            else:
                if isinstance(value, dict):
                    dicts.append(value)
                i = end
        else:
            i = pos + 1

    return dicts
```

