import json
import unicodedata


def decode_base64_json_values(json_text: str) -> dict[str, str]:
    if not isinstance(json_text, str):
        raise ValueError("Input must be a JSON string.")

    try:
        data = json.loads(json_text)
    except json.JSONDecodeError as exc:
        raise ValueError("Invalid JSON.") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON root must be an object.")

    result: dict[str, str] = {}
    for key, value in data.items():
        if not isinstance(value, str):
            raise ValueError(f"Value for key {key!r} must be a base64 string.")

        try:
            decoded_bytes = base64.b64decode(value, validate=True)
            decoded_text = decoded_bytes.decode("utf-8")
        except (binascii.Error, UnicodeDecodeError, ValueError) as exc:
            raise ValueError(f"Invalid base64 UTF-8 value for key {key!r}.") from exc

        result[key] = unicodedata.normalize("NFC", decoded_text)

    return result
```

### How it works:
1. **JSON parsing:** Uses `json.loads` and ensures the root JSON value is an object (`dict`), raising `ValueError` otherwise.
2. **Base64 validation & decoding:** Uses `base64.b64decode(value, validate=True)` so invalid characters or padding errors raise `ValueError`, then decodes the resulting bytes as UTF-8.
3. **Unicode normalization:** Applies `unicodedata.normalize("NFC", decoded_text)` to each decoded string before storing it in the returned dictionary.

